// Turns the two probes into one plain answer, so a failed setup says why.
const health = $('Health (no key needed)').first().json;
const roster = $('Roster (key required)').first().json;

// Three things can be wrong now, not two: the hub, the game behind it, or the key. The hub
// answers /api/health without one and reports the link to Minecraft, so they come apart.
const reachable = health && health.ok === true;
const running = health && health.minecraft && health.minecraft.online === true;
const authorised = roster && Array.isArray(roster.drones);

let verdict;
if (!reachable) {
  verdict = 'CANNOT REACH THE HUB. Check that server.py is running, that hub points at it, and '
          + '- on n8n Cloud - that your tunnel is up.';
} else if (!running) {
  verdict = 'THE HUB IS UP BUT MINECRAFT IS NOT. Start the Fabric server. The hub calls it on '
          + '127.0.0.1:8090 and reports what it finds under health.minecraft.';
} else if (!authorised) {
  verdict = 'REACHED THE HUB BUT WAS REJECTED. Attach the "Firekeep Hub" header-auth credential '
          + '(Authorization = Bearer <FIREKEEP_API_KEY, from the hub>) to the roster node.';
} else if (roster.count === 0) {
  verdict = 'WORKING, but there are no drones yet. Spawn one: /drone spawn ~ ~5 ~ drone_01';
} else {
  verdict = `WORKING. ${roster.count} drone(s): ` + roster.drones.map(d => `${d.id} (${d.status})`).join(', ');
}

return [{ json: {
  verdict,
  reachable,
  running,
  authorised,
  minecraft: health && health.minecraft,
  n8n: health && health.n8n,
  secured: health && health.secured,
  drones: roster && roster.drones,
} }];
